    "title": "The Invisible Architecture of an Agentic Workflow",
    "category": "AI Systems",
    "date": "2026-05-09",
    "dateDisplay": "May 9, 2026",
    "readTime": "8 min read",
    "cover": "https://images.unsplash.com/photo-1677442136019-21780ecad995?w=1400&h=600&fit=crop",
